macro_rules! AttributeDuplicates {
    () => {
        # [doc = " How to handle multiple duplicate attributes on the same item."] # [derive (Clone , Copy , Default)] pub enum AttributeDuplicates { # [doc = " Duplicates of this attribute are allowed."] # [doc = ""] # [doc = " This should only be used with attributes where duplicates have semantic"] # [doc = " meaning, or some kind of \"additive\" behavior. For example, `#[warn(..)]`"] # [doc = " can be specified multiple times, and it combines all the entries. Or use"] # [doc = " this if there is validation done elsewhere."] # [default] DuplicatesOk , # [doc = " Duplicates after the first attribute will be an unused_attribute warning."] # [doc = ""] # [doc = " This is usually used for \"word\" attributes, where they are used as a"] # [doc = " boolean marker, like `#[used]`. It is not necessarily wrong that there"] # [doc = " are duplicates, but the others should probably be removed."] WarnFollowing , # [doc = " Same as `WarnFollowing`, but only issues warnings for word-style attributes."] # [doc = ""] # [doc = " This is only for special cases, for example multiple `#[macro_use]` can"] # [doc = " be warned, but multiple `#[macro_use(...)]` should not because the list"] # [doc = " form has different meaning from the word form."] WarnFollowingWordOnly , # [doc = " Duplicates after the first attribute will be an error."] # [doc = ""] # [doc = " This should be used where duplicates would be ignored, but carry extra"] # [doc = " meaning that could cause confusion. For example, `#[stable(since=\"1.0\")]"] # [doc = " #[stable(since=\"2.0\")]`, which version should be used for `stable`?"] ErrorFollowing , # [doc = " Duplicates preceding the last instance of the attribute will be an error."] # [doc = ""] # [doc = " This is the same as `ErrorFollowing`, except the last attribute is the"] # [doc = " one that is \"used\". This is typically used in cases like codegen"] # [doc = " attributes which usually only honor the last attribute."] ErrorPreceding , # [doc = " Duplicates after the first attribute will be an unused_attribute warning"] # [doc = " with a note that this will be an error in the future."] # [doc = ""] # [doc = " This should be used for attributes that should be `ErrorFollowing`, but"] # [doc = " because older versions of rustc silently accepted (and ignored) the"] # [doc = " attributes, this is used to transition."] FutureWarnFollowing , # [doc = " Duplicates preceding the last instance of the attribute will be a"] # [doc = " warning, with a note that this will be an error in the future."] # [doc = ""] # [doc = " This is the same as `FutureWarnFollowing`, except the last attribute is"] # [doc = " the one that is \"used\". Ideally these can eventually migrate to"] # [doc = " `ErrorPreceding`."] FutureWarnPreceding , }
    };
}

AttributeDuplicates!()